CREATE OR REPLACE VIEW DBP_VIEW.V_FLW_DATENPOOL_OLD AS SELECT VERTEILPROZESS_ID, MANDANT_ID, SYSTEM_ID, TRIM (DATENPOOL_SATZART_ID) AS DATENPOOL_SATZART_ID, DAT_PRODUKTION, OBJEKT_ID, WERK_ID, DAT_LIEF, DAT_MAT_BEREITSTLLG, ZEIT_MAT_BEREITSTLLG, TRIM (FLW_TOURART_ID) AS FLW_TOURART_ID, FLW_KUNDE_ID, TRIM (VERK_MENGE_EINH_ID) AS VERK_MENGE_EINH_ID, ANZ_KOLLI_PRODUZIER, TRIM (KOMM_AUFTRAG_STATUS_ID) AS KOMM_AUFTRAG_STATUS_ID, TRIM (HANDLING_UNIT_ID_EXT) AS HANDLING_UNIT_ID_EXT, TRIM (LAGERNUMMER_ID) AS LAGERNUMMER_ID, FLW_ART_ID, LIEF_BELEG_ID, FLW_ART_ID_VERPACKUNG, TRIM (VERP_MENGE_EINH_ID) AS VERP_MENGE_EINH_ID, MENGE_PRODUZIERT, MENGE_PROGNOSE, KOLLI_VOL, TRIM (KOLLI_VOL_EINH_ID) AS KOLLI_VOL_EINH_ID, MENGE_ABSOLUT, MENGE_BESTAND, TD_INSERT, TD_UPDATE FROM DBP_DATA.FLW_DATENPOOL;